def _win_split(s):
    # Implementation based on the Windows Command Line Parser
    # https://docs.microsoft.com/en-us/previous-versions/windows/it-pro/windows-xp/bb490954(v=technet.10)
    tokens = []
    token = ''
    in_quote = False
    in_escape = False

    for c in s:
        if in_escape:
            token += c
            in_escape = False
        elif c == '\\':
            in_escape = True
        elif c == '"':
            if in_quote:
                token += c
            in_quote = not in_quote
        elif c in ' \t':
            if token:
                tokens.append(token)
                token = ''
        else:
            token += c

    if token:
        tokens.append(token)

    return tokens

