def validate_from_file(yaml_file):
    """
    Loads and validates that a YAML file has all required fields.

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """
    # Open the YAML file
    with open(yaml_file, 'r') as f:
        data = yaml.safe_load(f)

    # Check if all mandatory fields are present
    for field in ['name', 'version', 'description']:
        if field not in data:
            raise IRValidatorException(f'Mandatory field "{field}" is missing in YAML file')

    # Check if all fields have the correct type
    for field, value in data.items():
        if field == 'name':
            if not isinstance(value, str):
                raise IRValidatorException(f'Field "name" must be a string')
        elif field == 'version':
            if not isinstance(value, str):
                raise IRValidatorException(f'Field "version" must be a string')
        elif field == 'description':
            if not isinstance(value, str):
                raise IRValidatorException(f'Field "description" must be a string')
        else:
            raise IRValidatorException(f'Invalid field "{field}" in YAML file')

    # Return the data
    return data

