def _convert_non_cli_args(self, parser_name, values_dict):
    """
    Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """

    # Handle boolean arguments
    for arg in ["--help", "-h"]:
        if arg in values_dict:
            values_dict[arg] = True

    # Handle integer arguments
    for arg in ["--port", "-p"]:
        if arg in values_dict:
            try:
                values_dict[arg] = int(values_dict[arg])
            except ValueError:
                raise ValueError(f"Invalid value for {arg}: {values_dict[arg]}")

    # Handle string arguments
    for arg in ["--name", "-n"]:
        if arg in values_dict:
            values_dict[arg] = str(values_dict[arg])

    # Handle list arguments
    for arg in ["--list", "-l"]:
        if arg in values_dict:
            values_dict[arg] = values_dict[arg].split(",")

    # Handle dictionary arguments
    for arg in ["--dict", "-d"]:
        if arg in values_dict:
            values_dict[arg] = json.loads(values_dict[arg])

    # Handle file arguments
    for arg in ["--file", "-f"]:
        if arg in values_dict:
            with open(values_dict[arg], "r") as f:
                values_dict[arg] = f.read()

    # Handle command arguments
    for arg in ["--command", "-c"]:
        if arg in values_dict:
            values_dict[arg] = shlex.split(values_dict[arg])

    # Handle environment variables
    for arg in ["--env", "-e"]:
        if arg in values_dict:
            values_dict[arg] = os.environ.get(values_dict[arg])

def get_plugin_spec_flatten_dict(plugin_dir):
    """
    Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    plugin_spec = get_plugin_spec(plugin_dir)
    flatten_dict = {}
    for key, value in plugin_spec.items():
        if isinstance(value, dict):
            for subkey, subvalue in value.items():
                flatten_dict[f"{key}.{subkey}"] = subvalue
        else:
            flatten_dict[key] = value
    return flatten_dict
